INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3220633, 451151, 41337, '<td valign="top">Good capture. I particularly like how you composed the shot. For me it could be a bit brighter and sharper but otherwise this is a very good keepsake. Good luck.</td>', 'Good capture. I particularly like how you composed the shot. For me it could be a bit brighter and sharper but otherwise this is a very good keepsake. Good luck.', '2007-01-12 15:48:51.000000', NULL, 1),
(3220638, 447982, 22537, '<td valign="top">Cool bird shot and I like the focus on the subject.  As you are likely aware, the twig in the foreground is distracting.  Other than that, nice image.  Good luck!</td>', 'Cool bird shot and I like the focus on the subject.  As you are likely aware, the twig in the foreground is distracting.  Other than that, nice image.  Good luck!', '2007-01-12 15:49:44.000000', NULL, 1),
(3220644, 449733, 22537, '<td valign="top">I like the treatment of this image as it appears forelorn and whimsical.Though ou may not agree, a clean frame would have contained the image nicely.  Either way, you''ll surely do well.  Good luck!</td>', 'I like the treatment of this image as it appears forelorn and whimsical.Though ou may not agree, a clean frame would have contained the image nicely.  Either way, you''ll surely do well.  Good luck!', '2007-01-12 15:51:15.000000', NULL, 1),
(3220650, 450040, 41337, '<td valign="top">A visual treat. My only nitpick is the sky in the upper right corner seems too dark for the scene. It appears to go from bright (on the left) to dark too quickly.</td>', 'A visual treat. My only nitpick is the sky in the upper right corner seems too dark for the scene. It appears to go from bright (on the left) to dark too quickly.', '2007-01-12 15:52:50.000000', NULL, 1),
(3220655, 450961, 22537, '<td valign="top">This is such a fun shot and a real challenge with the DOF.  I suspect that the rushed pace of the subjects made a smaller aperature an impossibility. ;-)  Just funnin! Great shot and I hope it does well for you.</td>', 'This is such a fun shot and a real challenge with the DOF.  I suspect that the rushed pace of the subjects made a smaller aperature an impossibility. ;-)  Just funnin! Great shot and I hope it does well for you.', '2007-01-12 15:53:34.000000', NULL, 1),
