(3225530, 451450, 43774, '<td valign="top">Such a gorgeous scene!!!</td>', 'Such a gorgeous scene!!!', '2007-01-13 12:01:17.000000', NULL, 1),
(3225531, 449642, 3087, '<td valign="top">Beautiful - the complete absence of any distracting detail in the water really focuses attention on the bird, reflection and abstract shapes of the image too.</td>', 'Beautiful - the complete absence of any distracting detail in the water really focuses attention on the bird, reflection and abstract shapes of the image too.', '2007-01-13 12:01:32.000000', NULL, 1),
(3225533, 449153, 43774, '<td valign="top">Love the fisheye effect, gorgeous deep colours</td>', 'Love the fisheye effect, gorgeous deep colours', '2007-01-13 12:01:38.000000', NULL, 1),
(3225534, 447982, 43774, '<td valign="top">A bit grainy but a gorgeous photo</td>', 'A bit grainy but a gorgeous photo', '2007-01-13 12:01:51.000000', NULL, 1),
