(3225557, 451045, 39632, '<td valign="top">didn''t quite freeze the motion enough</td>', 'didn''t quite freeze the motion enough', '2007-01-13 12:04:55.000000', NULL, 1),
(3225559, 450976, 43774, '<td valign="top">Surreal photo! Dramatic sky and light, those 2 people really stand out with their bright clothes that contrast with the rest of the scene</td>', 'Surreal photo! Dramatic sky and light, those 2 people really stand out with their bright clothes that contrast with the rest of the scene', '2007-01-13 12:05:15.000000', NULL, 1),
