(3229834, 451937, 11920, '<td valign="top">very cute</td>', 'very cute', '2007-01-14 11:54:20.000000', NULL, 1),
(3229836, 448175, 7628, '<td valign="top">Dynamic!  The clouds, ripples in the water and the boat point to the horizon -the diagonal helps to emphasize that.  I wish there were more detail in the shadows. 7</td>', 'Dynamic!  The clouds, ripples in the water and the boat point to the horizon -the diagonal helps to emphasize that.  I wish there were more detail in the shadows. 7', '2007-01-14 11:54:41.000000', NULL, 1),
