INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3231133, 451132, 35229, '<td valign="top">Would''nt this be better in color?</td>', 'Would''nt this be better in color?', '2007-01-14 18:19:26.000000', NULL, 1),
(3231134, 449372, 4793, '<td valign="top">Beautiful</td>', 'Beautiful', '2007-01-14 18:19:28.000000', NULL, 1),
(3231139, 447767, 35229, '<td valign="top">The black frame is not good. Great photo otherwise.</td>', 'The black frame is not good. Great photo otherwise.', '2007-01-14 18:20:10.000000', NULL, 1),
(3231140, 451102, 7485, '<td valign="top">Environmental portraiture at its best!</td>', 'Environmental portraiture at its best!', '2007-01-14 18:20:19.000000', NULL, 1),
(3231141, 447860, 10485, '<td valign="top">Great point of view...should be hanging up !</td>', 'Great point of view...should be hanging up !', '2007-01-14 18:20:32.000000', NULL, 1),
(3231144, 447804, 35229, '<td valign="top">Should be looking into the camera.</td>', 'Should be looking into the camera.', '2007-01-14 18:20:35.000000', NULL, 1),
(3231145, 449149, 35229, '<td valign="top">This is to cool pickture. I am giving you full house.</td>', 'This is to cool pickture. I am giving you full house.', '2007-01-14 18:21:04.000000', NULL, 1),
(3231146, 450814, 10485, '<td valign="top">surreal !</td>', 'surreal !', '2007-01-14 18:21:58.000000', NULL, 1),
(3231148, 447971, 35229, '<td valign="top">I did not think that I would be giving pictures under 5 in this Best of challenge. But it happened now. The pic it blurry and grainy.</td>', 'I did not think that I would be giving pictures under 5 in this Best of challenge. But it happened now. The pic it blurry and grainy.', '2007-01-14 18:22:06.000000', NULL, 1),
(3231149, 448910, 35229, '<td valign="top">Have''nt I seen this face somewhere before?</td>', 'Have''nt I seen this face somewhere before?', '2007-01-14 18:22:48.000000', NULL, 1),
(3231150, 451719, 10485, '<td valign="top">looks like an 1920''s color slide from africa...good job.</td>', 'looks like an 1920''s color slide from africa...good job.', '2007-01-14 18:22:57.000000', NULL, 1),
(3231153, 450749, 35229, '<td valign="top">I like the toning. Is it negative? This is a great photo worthy on the wall.</td>', 'I like the toning. Is it negative? This is a great photo worthy on the wall.', '2007-01-14 18:23:42.000000', NULL, 1),
(3231158, 448776, 35229, '<td valign="top">Snapshot of a dog on the carpet. The posing of the ears do little to help the image.</td>', 'Snapshot of a dog on the carpet. The posing of the ears do little to help the image.', '2007-01-14 18:24:16.000000', NULL, 1),
(3231162, 451341, 35229, '<td valign="top">Blue Lagoon? I bet. Nice perspective.</td>', 'Blue Lagoon? I bet. Nice perspective.', '2007-01-14 18:24:54.000000', NULL, 1),
(3231166, 447883, 35229, '<td valign="top">I like this in every way. The sky is very beautyful and the calm water helps alot. Great work.</td>', 'I like this in every way. The sky is very beautyful and the calm water helps alot. Great work.', '2007-01-14 18:26:57.000000', NULL, 1),
(3231168, 450569, 35229, '<td valign="top">Damn those selective saturation pictures. The red blouse takes all the attention from the cool surroundings.</td>', 'Damn those selective saturation pictures. The red blouse takes all the attention from the cool surroundings.', '2007-01-14 18:27:59.000000', NULL, 1),
(3231170, 451829, 7485, '<td valign="top">Marvelous colors, lighting, and composition. Would be a 10 from me, but what ruins it is the unnatural texture on everything else than the waterfall. It looks like a photograph of a waterfall inserted into a weird pointillist landscape painting. 7</td>', 'Marvelous colors, lighting, and composition. Would be a 10 from me, but what ruins it is the unnatural texture on everything else than the waterfall. It looks like a photograph of a waterfall inserted into a weird pointillist landscape painting. 7', '2007-01-14 18:28:46.000000', NULL, 1),
(3231173, 449167, 35229, '<td valign="top">Var einmitt að velta því fyrir mér hvenær ég sæi þessa aftur. Frábær mynd. Lítur út eins og einhverskonar ofurmenni ;) Færð fullt hús frá mér. Gangi þér vel.</td>', 'Var einmitt að velta því fyrir mér hvenær ég sæi þessa aftur. Frábær mynd. Lítur út eins og einhverskonar ofurmenni ;) Færð fullt hús frá mér. Gangi þér vel.', '2007-01-14 18:29:20.000000', NULL, 1),
(3231176, 451366, 7485, '<td valign="top">Ouch, that much over-saturation hurts the eyes!</td>', 'Ouch, that much over-saturation hurts the eyes!', '2007-01-14 18:30:04.000000', NULL, 1),
(3231179, 451863, 35229, '<td valign="top">I hope you gave some money.</td>', 'I hope you gave some money.', '2007-01-14 18:32:17.000000', NULL, 1),
(3231180, 451856, 35229, '<td valign="top">You could probably sell them this picture.</td>', 'You could probably sell them this picture.', '2007-01-14 18:32:44.000000', NULL, 1),
(3231181, 448781, 2764, '<td valign="top">gasp! 10</td>', 'gasp! 10', '2007-01-14 18:32:50.000000', NULL, 1),
(3231185, 448017, 35229, '<td valign="top">This is neat. Good eye there. Giving a 9.</td>', 'This is neat. Good eye there. Giving a 9.', '2007-01-14 18:33:32.000000', NULL, 1),
(3231187, 450526, 35229, '<td valign="top">The sunflares are ruining the pic.</td>', 'The sunflares are ruining the pic.', '2007-01-14 18:34:01.000000', NULL, 1),
(3231191, 448254, 35229, '<td valign="top">Another background could have made this pic much better. But it is very good already.</td>', 'Another background could have made this pic much better. But it is very good already.', '2007-01-14 18:34:46.000000', NULL, 1),
(3231195, 451741, 7485, '<td valign="top">This one would definitely have benefitted from using the full 720 pixel width that we are allowed in this challenge. Also darkening the whole background would make the colors look richer.</td>', 'This one would definitely have benefitted from using the full 720 pixel width that we are allowed in this challenge. Also darkening the whole background would make the colors look richer.', '2007-01-14 18:36:16.000000', NULL, 1),
(3231198, 448004, 35229, '<td valign="top">This is a favourite for me. Great photo descriping the smallness of man. The centering of the subject is crucial for this picture. Love it, hope it wins. Good luck.</td>', 'This is a favourite for me. Great photo descriping the smallness of man. The centering of the subject is crucial for this picture. Love it, hope it wins. Good luck.', '2007-01-14 18:36:52.000000', NULL, 1),
(3231200, 451741, 35229, '<td valign="top">Way to small.</td>', 'Way to small.', '2007-01-14 18:38:01.000000', NULL, 1),
(3231203, 450967, 35229, '<td valign="top">Add a little time and it would have been better.</td>', 'Add a little time and it would have been better.', '2007-01-14 18:38:55.000000', NULL, 1),
(3231205, 451644, 35229, '<td valign="top">Solar eclipse is a remarkable thing and hard to capture so it will be beautyful I suppose. It is not working here.</td>', 'Solar eclipse is a remarkable thing and hard to capture so it will be beautyful I suppose. It is not working here.', '2007-01-14 18:39:41.000000', NULL, 1),
(3231210, 451842, 35229, '<td valign="top">To complicated picture. Ropes everywhere. Are the your subject or the ship?</td>', 'To complicated picture. Ropes everywhere. Are the your subject or the ship?', '2007-01-14 18:40:55.000000', NULL, 1),
(3231213, 447767, 7485, '<td valign="top">The lighting and color is gorgeous, but I find the jagged outlines distracting. They are quite noticeable on the crow in the middle. Also there are thin halos around the two right trees, and along the top and bottom of the image. Doesn''t look like USM, but maybe some other form of sharpening done too aggressively?</td>', 'The lighting and color is gorgeous, but I find the jagged outlines distracting. They are quite noticeable on the crow in the middle. Also there are thin halos around the two right trees, and along the top and bottom of the image. Doesn''t look like USM, but maybe some other form of sharpening done too aggressively?', '2007-01-14 18:41:33.000000', NULL, 1),
(3231214, 450989, 35229, '<td valign="top">Is it leaning to the left? Cool photo otherwise.</td>', 'Is it leaning to the left? Cool photo otherwise.', '2007-01-14 18:41:37.000000', NULL, 1),
(3231217, 448572, 35229, '<td valign="top">Little pink ridinghood. ;) Cute kid.</td>', 'Little pink ridinghood. ;) Cute kid.', '2007-01-14 18:42:50.000000', NULL, 1),
(3231218, 448505, 7485, '<td valign="top">There''s something really weird going on with these clouds, HDR gone wild?</td>', 'There''s something really weird going on with these clouds, HDR gone wild?', '2007-01-14 18:42:51.000000', NULL, 1),
(3231223, 451871, 35229, '<td valign="top">This is one of the "on the wall" pictures. Love the toning.</td>', 'This is one of the "on the wall" pictures. Love the toning.', '2007-01-14 18:43:57.000000', NULL, 1),
(3231226, 451952, 35229, '<td valign="top">It is hard to believe that this is your best of the year.</td>', 'It is hard to believe that this is your best of the year.', '2007-01-14 18:44:44.000000', NULL, 1),
(3231231, 450708, 6999, '<td valign="top">Strong sense of the enormity of the sky, although there''s likewise a strong sense of too much processing in those clouds.</td>', 'Strong sense of the enormity of the sky, although there''s likewise a strong sense of too much processing in those clouds.', '2007-01-14 18:45:51.000000', NULL, 1),
(3231232, 448505, 35229, '<td valign="top">The sky is a bit to much for me. I think you went a little awol on the Photoshop there.</td>', 'The sky is a bit to much for me. I think you went a little awol on the Photoshop there.', '2007-01-14 18:46:08.000000', NULL, 1),
(3231235, 448898, 35229, '<td valign="top">With a plummer! (he he). Funny photo.</td>', 'With a plummer! (he he). Funny photo.', '2007-01-14 18:46:48.000000', NULL, 1),
(3231237, 451727, 7485, '<td valign="top">An incredibly beautiful scene, but a very noisy image. And even worse, there''s horizontal structure to the noise, most obvious near the bottom of the image. You could fix it with NoiseNinja or NeatImage, but it would be a lot of work because you couldn''t use the same setting for the foliage as the rest of the image.</td>', 'An incredibly beautiful scene, but a very noisy image. And even worse, there''s horizontal structure to the noise, most obvious near the bottom of the image. You could fix it with NoiseNinja or NeatImage, but it would be a lot of work because you couldn''t use the same setting for the foliage as the rest of the image.', '2007-01-14 18:46:54.000000', NULL, 1),
(3231241, 451826, 6999, '<td valign="top">I''m quite taken with the little guy on the end, who doesn''t seem to know that he should be holding onto the others, and is just going is own way.</td>', 'I''m quite taken with the little guy on the end, who doesn''t seem to know that he should be holding onto the others, and is just going is own way.', '2007-01-14 18:48:22.000000', NULL, 1),
(3231242, 448260, 35229, '<td valign="top">You should frame this one. Great portrait and great afterwork.</td>', 'You should frame this one. Great portrait and great afterwork.', '2007-01-14 18:48:48.000000', NULL, 1),
(3231245, 447519, 35229, '<td valign="top">Very beautyful. Giving a 10.</td>', 'Very beautyful. Giving a 10.', '2007-01-14 18:49:56.000000', NULL, 1),
(3231249, 448260, 64929, '<td valign="top">An outstanding portrait! What an adorable little miss! &lt;9&gt;</td>', 'An outstanding portrait! What an adorable little miss! <9>', '2007-01-14 18:51:10.000000', NULL, 1),
(3231251, 448180, 35229, '<td valign="top">Composition perfect.</td>', 'Composition perfect.', '2007-01-14 18:51:47.000000', NULL, 1),
(3231253, 449145, 35229, '<td valign="top">Something very off here.</td>', 'Something very off here.', '2007-01-14 18:52:08.000000', NULL, 1),
(3231258, 451940, 35229, '<td valign="top">Cool.</td>', 'Cool.', '2007-01-14 18:52:39.000000', NULL, 1),
(3231260, 451876, 54672, '<td valign="top">awesome postprocessing..............is it the DRAGANIZER effect or something else????????<br/>Il be pleased if you let me know !!!</td>', 'awesome postprocessing..............is it the DRAGANIZER effect or something else????????Il be pleased if you let me know !!!', '2007-01-14 18:52:48.000000', NULL, 1),
(3231262, 450858, 6999, '<td valign="top">Interesting take on, in this challenge, a moderately common subject - the zoo animal. The model-esque pose of the front legs is intriguing, and the lines throughout add a sense of understanding.</td>', 'Interesting take on, in this challenge, a moderately common subject - the zoo animal. The model-esque pose of the front legs is intriguing, and the lines throughout add a sense of understanding.', '2007-01-14 18:52:50.000000', NULL, 1),
(3231265, 447766, 35229, '<td valign="top">They look so wise, dont they?</td>', 'They look so wise, dont they?', '2007-01-14 18:53:16.000000', NULL, 1),
(3231271, 449543, 7485, '<td valign="top">Ouch, too much NeatImage/NoiseNinja! The model''s hair has completely lost it''s texture. This makes her skin look nice, so your best bet would have been to manually mask out her hair before applying the filter. Also, I think that catching her looking into the camera would have produced a more powerful image.</td>', 'Ouch, too much NeatImage/NoiseNinja! The model''s hair has completely lost it''s texture. This makes her skin look nice, so your best bet would have been to manually mask out her hair before applying the filter. Also, I think that catching her looking into the camera would have produced a more powerful image.', '2007-01-14 18:55:09.000000', NULL, 1),
(3231272, 451450, 35229, '<td valign="top">And who could have taken this one I wonder? ;) Great photo, good luck.</td>', 'And who could have taken this one I wonder? ;) Great photo, good luck.', '2007-01-14 18:55:26.000000', NULL, 1),
(3231278, 449845, 35229, '<td valign="top">Looks more like blackberry to me. Way to dark.</td>', 'Looks more like blackberry to me. Way to dark.', '2007-01-14 18:56:08.000000', NULL, 1),
(3231287, 451933, 8624, '<td valign="top">is that a tick on your eye? eeeew. cool for the cringe factor though.</td>', 'is that a tick on your eye? eeeew. cool for the cringe factor though.', '2007-01-14 18:59:49.000000', NULL, 1),
(3231288, 450003, 35229, '<td valign="top">Poor girl looks like she is cold and unhappy. The photo is good in a disturbing kind of way.</td>', 'Poor girl looks like she is cold and unhappy. The photo is good in a disturbing kind of way.', '2007-01-14 18:59:52.000000', NULL, 1),
(3231291, 448446, 35229, '<td valign="top">Þessi versnar ekkert með aldrinum. Verður áhugavert að sjá hvernig henni gengur hérna.</td>', 'Þessi versnar ekkert með aldrinum. Verður áhugavert að sjá hvernig henni gengur hérna.', '2007-01-14 19:01:14.000000', NULL, 1),
(3231292, 451791, 35229, '<td valign="top">The framing is way to much.</td>', 'The framing is way to much.', '2007-01-14 19:01:55.000000', NULL, 1),
(3231296, 448572, 8624, '<td valign="top">a bit out of focus and her shoes are clipped at the bottom of the frame, but this is such a beautiful child in a great outfit that it still works pretty well.</td>', 'a bit out of focus and her shoes are clipped at the bottom of the frame, but this is such a beautiful child in a great outfit that it still works pretty well.', '2007-01-14 19:03:47.000000', NULL, 1),
(3231298, 448169, 8624, '<td valign="top">I like the high key and the tonal processing. I''m not big on tats, but you have highlighted them effectively here with your models</td>', 'I like the high key and the tonal processing. I''m not big on tats, but you have highlighted them effectively here with your models', '2007-01-14 19:04:54.000000', NULL, 1),
(3231302, 451852, 35229, '<td valign="top">I would have titled it "Long face" It seems awkward somehow.</td>', 'I would have titled it "Long face" It seems awkward somehow.', '2007-01-14 19:07:06.000000', NULL, 1),
(3231305, 449390, 35229, '<td valign="top">Great moment.</td>', 'Great moment.', '2007-01-14 19:07:50.000000', NULL, 1),
(3231306, 448260, 8624, '<td valign="top">a bot over processed on the whites of her eyes, but a great portrait otherwise.</td>', 'a bot over processed on the whites of her eyes, but a great portrait otherwise.', '2007-01-14 19:08:01.000000', NULL, 1),
(3231307, 449496, 35229, '<td valign="top">It is both funny and a great photograph. Sharp and interesting. Nice work.</td>', 'It is both funny and a great photograph. Sharp and interesting. Nice work.', '2007-01-14 19:08:50.000000', NULL, 1),
(3231308, 449494, 35229, '<td valign="top">Somebody took a dump on his head. Evil looking creature.</td>', 'Somebody took a dump on his head. Evil looking creature.', '2007-01-14 19:09:45.000000', NULL, 1),
(3231312, 451923, 35229, '<td valign="top">Sad.</td>', 'Sad.', '2007-01-14 19:11:18.000000', NULL, 1),
