(3235614, 449785, 30982, '<td valign="top">Sweet, sweet shot.  Daddy''s gotta love this one.</td>', 'Sweet, sweet shot.  Daddy''s gotta love this one.', '2007-01-15 15:49:16.000000', NULL, 1),
(3235620, 449472, 811, '<td valign="top">Good use of negative space and leading lines.</td>', 'Good use of negative space and leading lines.', '2007-01-15 15:50:45.000000', NULL, 1),
