(3241746, 449622, 57392, '<td valign="top">nice and crisp photo,very sharp good job done,9</td>', 'nice and crisp photo,very sharp good job done,9', '2007-01-16 18:49:58.000000', NULL, 1),
(3241749, 451240, 32345, '<td valign="top">Must be great going home and seeing that. Very good pic.</td>', 'Must be great going home and seeing that. Very good pic.', '2007-01-16 18:50:26.000000', NULL, 1),
