(3241845, 449691, 32345, '<td valign="top">B&amp;W works really good with this picture.</td>', 'B&W works really good with this picture.', '2007-01-16 19:00:46.000000', NULL, 1),
(3241847, 447808, 53243, '<td valign="top">I see him, but he''s not really that interesting especially for a best of 2006 challenge.</td>', 'I see him, but he''s not really that interesting especially for a best of 2006 challenge.', '2007-01-16 19:00:57.000000', NULL, 1),
