(3248012, 451313, 811, '<td valign="top">I really like the composition and perspective on this one.</td>', 'I really like the composition and perspective on this one.', '2007-01-17 16:43:24.000000', NULL, 1),
(3248015, 449078, 29904, '<td valign="top">Normally I would be anoyed by a lack of focus, but it is clearly intentional like an impressionistic abatract. Nice.</td>', 'Normally I would be anoyed by a lack of focus, but it is clearly intentional like an impressionistic abatract. Nice.', '2007-01-17 16:43:45.000000', NULL, 1),
(3248022, 447519, 23430, '<td valign="top">Wow. This is awesome. A beautiful scene nicely composed and processed. Nice light to capture the texture of those mountains.</td>', 'Wow. This is awesome. A beautiful scene nicely composed and processed. Nice light to capture the texture of those mountains.', '2007-01-17 16:45:14.000000', NULL, 1),
