(3251395, 448521, 4517, '<td valign="top">Would be better facing front, always best to see the eyes.</td>', 'Would be better facing front, always best to see the eyes.', '2007-01-18 12:16:59.000000', NULL, 1),
(3251396, 451863, 30982, '<td valign="top">A powerful picture - processing is handled well, too.</td>', 'A powerful picture - processing is handled well, too.', '2007-01-18 12:17:02.000000', NULL, 1),
