INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3258237, 451193, 7778, '<td valign="top">Considering the quality of this image, I''d have the title as subject ''I''. "Me", IMHO, would suit something less consciously composed and cared for. Personally, I''d choose a formal name (first and last) to restore the honesty the glasses robbed your subject of.<br/> <br/>An interesting juxtaposition of genres, btw, cropped to leave no doubts. -<br/>Treatment, too, is aptly pushed and contained. -<br/>Texture, tone and line stand out as if in a fashion shot. -<br/> <br/>The dominance of the veiling elements (shades and hood) together with the tight, straight-on take and near-discomforting proximity of the subject amplify the underlying, inherent dualism that make this image and provide its mysterious energy.</td>', 'Considering the quality of this image, I''d have the title as subject ''I''. "Me", IMHO, would suit something less consciously composed and cared for. Personally, I''d choose a formal name (first and last) to restore the honesty the glasses robbed your subject of. An interesting juxtaposition of genres, btw, cropped to leave no doubts. -Treatment, too, is aptly pushed and contained. -Texture, tone and line stand out as if in a fashion shot. - The dominance of the veiling elements (shades and hood) together with the tight, straight-on take and near-discomforting proximity of the subject amplify the underlying, inherent dualism that make this image and provide its mysterious energy.', '2007-01-19 23:40:33.000000', NULL, 1),
(3258243, 451923, 50695, '<td valign="top">grotesque post-processing</td>', 'grotesque post-processing', '2007-01-19 23:42:05.000000', NULL, 1),
