(3261732, 451945, 48228, '<td valign="top">So sweet....</td>', 'So sweet....', '2007-01-21 06:42:48.000000', NULL, 1),
(3261792, 451727, 23394, '<td valign="top">a beautiful place, for sure, but there''s something horribly pixelated in this image in the trees and water.  given the sharpness of the mountains and sky, something just doesn''t seem right.</td>', 'a beautiful place, for sure, but there''s something horribly pixelated in this image in the trees and water.  given the sharpness of the mountains and sky, something just doesn''t seem right.', '2007-01-21 07:29:53.000000', NULL, 1),
(3261829, 447851, 61191, '<td valign="top">Wow, awesome find! But I think your should have lightened several parts (for example the foreground) more up during postprocessing.</td>', 'Wow, awesome find! But I think your should have lightened several parts (for example the foreground) more up during postprocessing.', '2007-01-21 07:51:53.000000', NULL, 1),
(3261832, 449975, 61191, '<td valign="top">Wow, cool action shot! (Is this you, Leroy?)</td>', 'Wow, cool action shot! (Is this you, Leroy?)', '2007-01-21 07:58:37.000000', NULL, 1),
