INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3262620, 448129, 68266, '<td valign="top">I find the white at the top of the hat distracting, otherwise a great capture, tighter crop might help.</td>', 'I find the white at the top of the hat distracting, otherwise a great capture, tighter crop might help.', '2007-01-21 15:05:49.000000', NULL, 1),
(3262681, 451961, 35947, '<td valign="top">Great reflection!</td>', 'Great reflection!', '2007-01-21 15:44:52.000000', NULL, 1),
(3262769, 447670, 35274, '<td valign="top">Loving the crazy DOF and warm colors.</td>', 'Loving the crazy DOF and warm colors.', '2007-01-21 16:36:31.000000', NULL, 1),
(3262775, 451132, 35274, '<td valign="top">Well that''s a pretty interesting cloud formation. Gives this shot a very odd composition, with the rock and the bush.</td>', 'Well that''s a pretty interesting cloud formation. Gives this shot a very odd composition, with the rock and the bush.', '2007-01-21 16:37:57.000000', NULL, 1),
(3262778, 450990, 35274, '<td valign="top">Oh lala. Wide angle, long exposure, HDR deliciousness. This should do very well here.</td>', 'Oh lala. Wide angle, long exposure, HDR deliciousness. This should do very well here.', '2007-01-21 16:39:26.000000', NULL, 1),
(3262781, 447829, 35274, '<td valign="top">Wow, what timing! Hope he didn''t crash and break his neck right after this shot was taken :P</td>', 'Wow, what timing! Hope he didn''t crash and break his neck right after this shot was taken :P', '2007-01-21 16:40:02.000000', NULL, 1),
(3262787, 447682, 35274, '<td valign="top">Aw, what a perfect shot of a lion. Composition, color, clarity, yada yada. All very good. He looks cuddly :]</td>', 'Aw, what a perfect shot of a lion. Composition, color, clarity, yada yada. All very good. He looks cuddly :]', '2007-01-21 16:43:29.000000', NULL, 1),
(3262792, 447759, 35274, '<td valign="top">Oooh, I know who''s this is ;]<br/>I love the minute details and that crazy DOF. Composition really stands out on this one as well.</td>', 'Oooh, I know who''s this is ;]I love the minute details and that crazy DOF. Composition really stands out on this one as well.', '2007-01-21 16:44:55.000000', NULL, 1),
(3262793, 448659, 35274, '<td valign="top">This is very cute and funny, but this qualifies as a snap shot to me. And most dpc voters are not fond of snap shots.</td>', 'This is very cute and funny, but this qualifies as a snap shot to me. And most dpc voters are not fond of snap shots.', '2007-01-21 16:46:28.000000', NULL, 1),
(3262795, 451767, 67258, '<td valign="top">Almost unreal looking!  A superb and truly interesting capture.</td>', 'Almost unreal looking!  A superb and truly interesting capture.', '2007-01-21 16:47:37.000000', NULL, 1),
(3262797, 451041, 67258, '<td valign="top">Such incredible detail in the bird''s plumage.</td>', 'Such incredible detail in the bird''s plumage.', '2007-01-21 16:48:25.000000', NULL, 1),
