(3269578, 448148, 53316, '<td valign="top">This brought a smile to my face.</td>', 'This brought a smile to my face.', '2007-01-23 03:14:22.000000', NULL, 1),
(3269579, 451936, 53316, '<td valign="top">The cropping could have been looser, and the "red eye" eliminated.  But the focus is great and the dog''s expression is priceless!</td>', 'The cropping could have been looser, and the "red eye" eliminated.  But the focus is great and the dog''s expression is priceless!', '2007-01-23 03:15:10.000000', NULL, 1),
