(3278068, 447759, 23394, '<td valign="top">beautiful, great detail, great colors.</td>', 'beautiful, great detail, great colors.', '2007-01-24 22:22:22.000000', NULL, 1),
(3278069, 451912, 23394, '<td valign="top">excellent shot!  that is right up there on my 2007 shot list--thanks for a great example!</td>', 'excellent shot!  that is right up there on my 2007 shot list--thanks for a great example!', '2007-01-24 22:22:25.000000', NULL, 1),
(3278070, 451745, 23394, '<td valign="top">a lovely image; just wish the sun was a little more offset.  that''s hardly a complaint, though, so please don''t take it as such.</td>', 'a lovely image; just wish the sun was a little more offset.  that''s hardly a complaint, though, so please don''t take it as such.', '2007-01-24 22:22:29.000000', NULL, 1),
(3278071, 449499, 23394, '<td valign="top">excellent work.  my only complaint is the centeredness of the image.  very hypnotic...</td>', 'excellent work.  my only complaint is the centeredness of the image.  very hypnotic...', '2007-01-24 22:22:33.000000', NULL, 1),
(3278072, 448496, 23394, '<td valign="top">fun shot.  due to the focus, you might consider cropping off the bottom stone, as it being oof is a bit of a distraction--it just doesn''t fit with everything else.</td>', 'fun shot.  due to the focus, you might consider cropping off the bottom stone, as it being oof is a bit of a distraction--it just doesn''t fit with everything else.', '2007-01-24 22:22:37.000000', NULL, 1),
(3278074, 451840, 23394, '<td valign="top">beautiful image.  it could possibly stand a bit more processing to bring out some of the washed out detail, though.  it''s just so tough, shooting through those hazy days...</td>', 'beautiful image.  it could possibly stand a bit more processing to bring out some of the washed out detail, though.  it''s just so tough, shooting through those hazy days...', '2007-01-24 22:22:42.000000', NULL, 1),
