INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3278087, 449938, 23394, '<td valign="top">that''s a wow-zer!  i can''t even imagine how much effort went into this image...</td>', 'that''s a wow-zer!  i can''t even imagine how much effort went into this image...', '2007-01-24 22:23:29.000000', NULL, 1),
(3278088, 447805, 23394, '<td valign="top">excellent capture.  really tells a story.</td>', 'excellent capture.  really tells a story.', '2007-01-24 22:23:34.000000', NULL, 1),
(3278089, 447572, 23394, '<td valign="top">sorry, but this just doesn''t do much for me.  i have an idea as to what you were after, but it seems more confused than well-executed.</td>', 'sorry, but this just doesn''t do much for me.  i have an idea as to what you were after, but it seems more confused than well-executed.', '2007-01-24 22:23:38.000000', NULL, 1),
