(3278735, 451369, 48228, '<td valign="top">Works for me...</td>', 'Works for me...', '2007-01-24 23:44:38.000000', NULL, 1),
(3278736, 451454, 23394, '<td valign="top">i have an idea as to what you were after here, but somehow it''s just not working for me.  the breakdown in the details seems to indicate a problem with the exposure.</td>', 'i have an idea as to what you were after here, but somehow it''s just not working for me.  the breakdown in the details seems to indicate a problem with the exposure.', '2007-01-24 23:44:40.000000', NULL, 1),
