INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3278757, 448950, 23394, '<td valign="top">wow, what a place to be.  talk about ''by still waters''...</td>', 'wow, what a place to be.  talk about ''by still waters''...', '2007-01-24 23:45:44.000000', NULL, 1),
(3278759, 450534, 23394, '<td valign="top">what''s that, a monument to E.T.?  your image has a surreal, almost dali-esque feel to it.</td>', 'what''s that, a monument to E.T.?  your image has a surreal, almost dali-esque feel to it.', '2007-01-24 23:45:56.000000', NULL, 1),
(3278761, 448659, 23394, '<td valign="top">cute and quirky, yes, but also an image that will probably do better in a scrapbook than in this challenge.  these snapshot images usually get hammered, but, that''s the nature of this site.</td>', 'cute and quirky, yes, but also an image that will probably do better in a scrapbook than in this challenge.  these snapshot images usually get hammered, but, that''s the nature of this site.', '2007-01-24 23:46:01.000000', NULL, 1),
(3278762, 451907, 23394, '<td valign="top">pardon me, i must make a mad dash to the freezer!  not sure how this will do in the challenge, but i''m sure enjoying it.</td>', 'pardon me, i must make a mad dash to the freezer!  not sure how this will do in the challenge, but i''m sure enjoying it.', '2007-01-24 23:46:06.000000', NULL, 1),
