(3278764, 447801, 48228, '<td valign="top">Nicely centered.....</td>', 'Nicely centered.....', '2007-01-24 23:46:11.000000', NULL, 1),
(3278765, 449473, 23394, '<td valign="top">excellent image.  misspelt title (gypsy).  you might consider looking at this with just a little more usm.  not a lot, just enough to bring even more character out of his face.  just my opinion, feel free to ignore.</td>', 'excellent image.  misspelt title (gypsy).  you might consider looking at this with just a little more usm.  not a lot, just enough to bring even more character out of his face.  just my opinion, feel free to ignore.', '2007-01-24 23:46:15.000000', NULL, 1),
