(3279054, 449773, 23394, '<td valign="top">what a precious moment.  not quite sure why, but the processing seems a bit off.</td>', 'what a precious moment.  not quite sure why, but the processing seems a bit off.', '2007-01-25 00:01:20.000000', NULL, 1),
(3279055, 451242, 23394, '<td valign="top">spot on!  expertly done, to say the least.</td>', 'spot on!  expertly done, to say the least.', '2007-01-25 00:01:24.000000', NULL, 1),
(3279057, 451666, 23394, '<td valign="top">marvelous study of colors and textures.  this image works for me on many, many different levels.  probably a bit too subtle for this challenge, though.</td>', 'marvelous study of colors and textures.  this image works for me on many, many different levels.  probably a bit too subtle for this challenge, though.', '2007-01-25 00:01:28.000000', NULL, 1),
