(3280112, 447568, 46314, '<td valign="top">Interesting ''retro'' processing. Highlights seem a bit harsh on the water though.</td>', 'Interesting ''retro'' processing. Highlights seem a bit harsh on the water though.', '2007-01-25 06:45:50.000000', NULL, 1),
(3280115, 451035, 46314, '<td valign="top">Nice photo. The spot is really emphasised well by the dull colours around it. Good focus and DOF.</td>', 'Nice photo. The spot is really emphasised well by the dull colours around it. Good focus and DOF.', '2007-01-25 06:46:37.000000', NULL, 1),
