(3281733, 451171, 24715, '<td valign="top">I like the silhouette here, excellent colors and composition.</td>', 'I like the silhouette here, excellent colors and composition.', '2007-01-25 15:21:01.000000', NULL, 1),
(3281735, 451028, 24715, '<td valign="top">The mountain stands out really well against the snow and sky. Great capture!</td>', 'The mountain stands out really well against the snow and sky. Great capture!', '2007-01-25 15:21:48.000000', NULL, 1),
(3281737, 451963, 54835, '<td valign="top">I love Macro Photography especially of flowers so this photo was right up my alley. Great shot, great color!</td>', 'I love Macro Photography especially of flowers so this photo was right up my alley. Great shot, great color!', '2007-01-25 15:22:16.000000', NULL, 1),
