(3281746, 449996, 24715, '<td valign="top">Excellent image. Why so small?</td>', 'Excellent image. Why so small?', '2007-01-25 15:24:17.000000', NULL, 1),
(3281750, 449982, 24715, '<td valign="top">Great focus and details. Also like the contrasting colors.</td>', 'Great focus and details. Also like the contrasting colors.', '2007-01-25 15:24:50.000000', NULL, 1),
