INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3282648, 450741, 42567, '<td valign="top">great snow picture!  I like it b/c its real snow and not a IR picture. 10</td>', 'great snow picture!  I like it b/c its real snow and not a IR picture. 10', '2007-01-25 19:47:27.000000', NULL, 1),
(3282654, 451079, 42567, '<td valign="top">thats crazy but good</td>', 'thats crazy but good', '2007-01-25 19:48:05.000000', NULL, 1),
(3282655, 448002, 42567, '<td valign="top">nice eagle picture!</td>', 'nice eagle picture!', '2007-01-25 19:48:27.000000', NULL, 1),
(3282661, 447683, 61191, '<td valign="top">Ah... looks like paradise really exists! What can I say? Awesome shot, awesome colors, awesome find!! Don''t know, if I like the two people sitting there... on the one hand, they add depth and interest to the photo but on the other hand they "ruin" the perfect landscape. Anyway: 10!</td>', 'Ah... looks like paradise really exists! What can I say? Awesome shot, awesome colors, awesome find!! Don''t know, if I like the two people sitting there... on the one hand, they add depth and interest to the photo but on the other hand they "ruin" the perfect landscape. Anyway: 10!', '2007-01-25 19:49:09.000000', NULL, 1),
(3282719, 448168, 15497, '<td valign="top">Whoa, Great looking photo, and two lovely cars! I want a SLR :)<br/>9</td>', 'Whoa, Great looking photo, and two lovely cars! I want a SLR :)9', '2007-01-25 20:06:24.000000', NULL, 1),
(3282721, 451912, 15497, '<td valign="top">Simply and a special composition. I enjoy the colors here! 7</td>', 'Simply and a special composition. I enjoy the colors here! 7', '2007-01-25 20:06:45.000000', NULL, 1),
(3282723, 450717, 15497, '<td valign="top">Magnificent, a true masterpiece! Just love how the road makes me go deeper into the frame. I may have used more saturation, but then again I love colors!  9</td>', 'Magnificent, a true masterpiece! Just love how the road makes me go deeper into the frame. I may have used more saturation, but then again I love colors!  9', '2007-01-25 20:07:24.000000', NULL, 1),
(3282724, 450127, 20941, '<td valign="top">A lovely portrait so well presented, sure to be a treasure for this litle one and her family always.</td>', 'A lovely portrait so well presented, sure to be a treasure for this litle one and her family always.', '2007-01-25 20:07:36.000000', NULL, 1),
(3282728, 451534, 15497, '<td valign="top">Fantastic! First 10 I''ve given, a true masterpiece! I love so many aspects of this photo, the composition, the subject facing away, the wedding dress, the tones, the dark contrast. If this was a wedding job, you aced it! Luck couple getting shots like these! again, 10! And hopefully a blue ribbon :)</td>', 'Fantastic! First 10 I''ve given, a true masterpiece! I love so many aspects of this photo, the composition, the subject facing away, the wedding dress, the tones, the dark contrast. If this was a wedding job, you aced it! Luck couple getting shots like these! again, 10! And hopefully a blue ribbon :)', '2007-01-25 20:08:23.000000', NULL, 1),
(3282730, 448415, 15497, '<td valign="top">Hehe, Really funny shot. He sort of lives in the wild, love the green color. 6</td>', 'Hehe, Really funny shot. He sort of lives in the wild, love the green color. 6', '2007-01-25 20:08:50.000000', NULL, 1),
(3282732, 449459, 15497, '<td valign="top">Great shot, simple composition, and lovely colors. The mist really makes this photo! 8</td>', 'Great shot, simple composition, and lovely colors. The mist really makes this photo! 8', '2007-01-25 20:09:11.000000', NULL, 1),
(3282735, 448176, 15497, '<td valign="top">Sorry but the composition doesn''t work for me. I like the diagonal lines, but the curves just seem a tad out of place. Also there is a slight halo effect around it due to sharpening, this can easily be fixed with a layermask. Maybe a different perspective would have a made a difference. 6</td>', 'Sorry but the composition doesn''t work for me. I like the diagonal lines, but the curves just seem a tad out of place. Also there is a slight halo effect around it due to sharpening, this can easily be fixed with a layermask. Maybe a different perspective would have a made a difference. 6', '2007-01-25 20:10:31.000000', NULL, 1),
(3282739, 450539, 15497, '<td valign="top">Great shot, I''d move all-in with these pocket ladies :-)<br/> <br/>I like the light and the colors, now did he win? 8</td>', 'Great shot, I''d move all-in with these pocket ladies :-) I like the light and the colors, now did he win? 8', '2007-01-25 20:11:02.000000', NULL, 1),
